<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free PDF Merge Online','description'=>'Merge multiple PDF files into one PDF directly in your browser.','url'=>'https://smarttoolz.in/tools/pdf-merge/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">PDF MERGE</span><h1>Merge PDF Files</h1><p>Select two or more PDFs and combine them into one document.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Choose PDFs<input id="f" type="file" accept="application/pdf" multiple></label><p id="list"></p><button id="go" class="tool-btn">Merge & Download</button><p id="out"></p></div></section></main><script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script><script>(()=>{const f=document.getElementById('f'),l=document.getElementById('list'),o=document.getElementById('out');f.onchange=()=>l.textContent=[...f.files].map(x=>x.name).join(' · ');document.getElementById('go').onclick=async()=>{if(f.files.length<2){o.textContent='Choose at least two PDFs.';return}o.textContent='Merging…';try{const out=await PDFLib.PDFDocument.create();for(const file of f.files){const src=await PDFLib.PDFDocument.load(await file.arrayBuffer());const pages=await out.copyPages(src,src.getPageIndices());pages.forEach(p=>out.addPage(p))}const bytes=await out.save(),blob=new Blob([bytes],{type:'application/pdf'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='merged.pdf';a.click();o.textContent='Merged successfully.'}catch(e){o.textContent='Could not merge these PDFs.'}}})();</script><?php smarttoolz_tool_page_end(); ?>